439	\end{proposition}
440	\begin{proof}
441	All $Q_t$ are f.p.\ (Lemma~\ref{lem:cov}(ii)), so $G(Q_t)=I_{\tau,A}(\Phi_{Q_t})$ by Lemma~\ref{lem:lanfp}, which is $A$ iff $\Phi_{Q_t}\subset\tau$; the restriction maps between nonzero terms are $\mathrm{id}_A$. If $\Phi_Q\not\subset\tau$, every term vanishes since $\Phi_Q\subset\Phi_{Q_t}$. Otherwise $\Phi_{Q_t}=\Phi_{\set(t)}$ by Lemma~\ref{lem:2}, applied to the composite $P\to Q$ (and $Q_t$ is the same pushout), so the complex is $\Hom(\tilde C(N_\tau),A)$. Exactness is Theorem~\ref{thm:D}, whose hypotheses hold: the members are f.p.\ under $Q$, every valuation of $Q$ factors through one (Lemma~\ref{lem:cov}(iv)), and $\Phi_Q\subset\tau$.
442	\end{proof}
443	
444	\begin{corollary}\label{cor:cech}
445	For $Q\in\fB$ and $\cU\in\Cov$ over $Q$, the augmented Čech complex of each $\Lan I^k$ on $\cU$ is exact.
446	\end{corollary}
447	\begin{proof}
448	Only objects of $\fB$ occur, and on $\fB$, $\Lan I^k=\prod_\tau\Lan I_{\tau,A_{k,\tau}}$ naturally (Lemma~\ref{lem:lanfp}(d)). Products of exact complexes are exact.
449	\end{proof}
450	
451	\subsection{Sheafification does not change values on f.p.\ objects}
452	We use the standard facts \cite[Exp.~II, \S3]{SGA4}: for a sieve $R$ generated by a family $\{U_i\to U\}$ with pushouts, $\Hom_{\PSh}(R,G)$ is the equalizer of $\prod G(U_i)\rightrightarrows\prod G(U_{ij})$; $G^+(U)=\colim_{R\in\cJ(U)}\Hom(R,G)$; and $G^\#=G^{++}$.
453	
454	\begin{lemma}\label{lem:plus}
455	Let $G$ be a presheaf such that for all $Q\in\fB$ and $\cU\in\Cov$ over $Q$ the sequence $0\to G(Q)\to\prod G(Q_i)\rightrightarrows\prod G(Q_{ij})$ is exact (an equalizer). Then $G(Q)\to G^\#(Q)$ is an isomorphism for every $Q\in\fB$.
456	\end{lemma}
457	\begin{proof}
458	$\cJ(Q)$ is directed under reverse inclusion (the intersection of two covering sieves is covering), and $G^+(Q)$ is the colimit over it. By Lemma~\ref{lem:cov}(iii), the sieves generated by members of $\Cov$ are cofinal in $\cJ(Q)$; a cofinal subset of a directed set is directed and computes the same colimit. On each of them $\Hom(R,G)=G(Q)$, compatibly with the transition maps, so $G(Q)\cong G^+(Q)$. For $\cU\in\Cov$, all of $Q,Q_i,Q_{ij}$ lie in $\fB$, where $G\to G^+$ is an isomorphism, so $G^+$ satisfies the same hypothesis. Repeating gives the claim for $G^{++}=G^\#$.
459	\end{proof}
460	
461	\begin{corollary}\label{cor:unit}
462	The following hold.
463	\begin{enumerate}[(a)]
464	\item $\Lan F$ satisfies the hypothesis of Lemma~\ref{lem:plus}.
465	\item For $Q\in\fB$, $F(\Phi_Q)\cong(\Lan F)(Q)\cong(\pi^{-1}F)(Q)$, naturally. In particular the unit $F\to\pi_*\pi^{-1}F$ is an isomorphism.
466	\item $(\pi^{-1}I^k)(Q)=I^k(\Phi_Q)$ on $\fB$, and $\check H^p(\cU,\pi^{-1}I^k)=0$ for $p>0$ and $\cU\in\Cov$.
467	\end{enumerate}
468	\end{corollary}
469	\begin{proof}
470	(a) Use the exact sequence $0\to\Lan F\to\Lan I^0\to\Lan I^1$ and Corollary~\ref{cor:cech} in degrees $-1,0,1$. If $s\in(\Lan F)(Q)$ restricts to $0$ on every $Q_i$, its image in $(\Lan I^0)(Q)$ does too, hence is $0$, so $s=0$. A compatible family $(s_i)$ glues in $\Lan I^0$ to some $t$; the image of $t$ in $(\Lan I^1)(Q)$ has all restrictions $0$, hence is $0$; so $t$ comes from some $s\in(\Lan F)(Q)$, and $s$ restricts to $s_i$ by injectivity of $(\Lan F)(Q_i)\to(\Lan I^0)(Q_i)$.
471	(b) follows from (a), Lemma~\ref{lem:plus} and Lemma~\ref{lem:lanfp}(a); the unit at $b$ is $F(b)\cong(\Lan F)(b)\to(\Lan F)^\#(b)$ and $b\in\fB$.
472	(c) The first statement is (b) for $F=I^k$. Hence on $\cU\in\Cov$ the Čech complex of $\pi^{-1}I^k$ is isomorphic to that of $\Lan I^k$, which is exact by Corollary~\ref{cor:cech}.
473	\end{proof}
474	
475	\subsection{A Cartan-type criterion}
476	The following is a version of a classical criterion of H.~Cartan for comparing Čech and derived functor cohomology; we include a proof adapted to the system $\Cov$.
477	
478	\begin{lemma}\label{lem:fact}
479	For an injective abelian sheaf $\cI$ on $(A_P^{\mathrm{op}},\cJ)$ and any family $\cU=\{U\to U_i\}_{i\in I}$ in $A_P$ (pushouts exist), $\check H^p(\cU,\cI)=0$ for $p>0$.
480	\end{lemma}
481	\begin{proof}
482	For an object $V$ let $\Z_V$ be the free abelian presheaf on $h_V=\Hom_{A_P}(V,-)$. Let $K_p=\bigoplus_{t\in I^{p+1}}\Z_{U_t}$ with the alternating face differential; by Yoneda, $\Hom_{\PSh}(K_\bullet,G)=\check C^\bullet(\cU,G)$. Evaluate at $W$: $K_\bullet(W)$ splits as a sum over $\psi\colon U\to W$, and the summand for $\psi$ is the ordered chain complex of the full simplex (with repetitions) on $T_\psi=\{(i,\varphi):\varphi\colon U_i\to W\text{ compatible with }\psi\}$. Prepending a fixed element of $T_\psi$ contracts it in positive degrees, and $H_0$ is $\Z$ if $T_\psi\neq\emptyset$ and $0$ otherwise. So $K_\bullet$ resolves the presheaf $\Z_R$ of the sieve $R$ generated by $\cU$. Sheafification is exact and $\Hom_{\Sh}(-,\cI)$ is exact, so $\check C^\bullet(\cU,\cI)=\Hom_{\Sh}(K_\bullet^\#,\cI)$ is exact in positive degrees.
483	\end{proof}
484	
485	\begin{proposition}\label{prop:cartan}
486	Let $G$ be an abelian sheaf on $(A_P^{\mathrm{op}},\cJ)$ with $\check H^p(\cU,G)=0$ for all $p>0$ and all $\cU\in\Cov$. Then $H^p(U,G)=0$ for all $p>0$ and all $U\in\fB$.
487	\end{proposition}
488	\begin{proof}
489	Embed $G\hookrightarrow\cI$ with $\cI$ an injective sheaf (abelian sheaves on a site form an abelian category with enough injectives \cite{Tohoku}), and let $\cQ=\cI/G$ (sheaf quotient). Then $G(W)=\ker(\cI(W)\to\cQ(W))$ for all $W$.
490	
491	(a) \emph{$\cI(V)\to\cQ(V)$ is onto for $V\in\fB$.} Take $s\in\cQ(V)$. It lifts locally on some covering sieve $R$. By Lemma~\ref{lem:cov}(iii) choose $\cV=\{V\to V_i\}\in\Cov$ with members in $R$ and lifts $t_i$ of $s|_{V_i}$. Then $c_{ij}:=t_j-t_i$ on $V_{ij}$ lies in $G(V_{ij})$ and is a Čech $1$-cocycle for $G$. Since $\check H^1(\cV,G)=0$, $c=dg$ with $g\in\check C^0(\cV,G)$. The family $(t_i-g_i)$ is compatible, so it glues in the sheaf $\cI$ to some $t$, and $t$ maps to $s$ because $\cQ$ is a sheaf and $t$, $s$ have the same restrictions to all $V_i$.
492	
493	(b) \emph{$\cQ$ satisfies the hypothesis.} For $\cU\in\Cov$ all the $U_t$ lie in $\fB$, so $0\to\check C(\cU,G)\to\check C(\cU,\cI)\to\check C(\cU,\cQ)\to0$ is exact by (a). In the long exact sequence $\check H^p(\cU,\cI)\to\check H^p(\cU,\cQ)\to\check H^{p+1}(\cU,G)$ the left term is $0$ for $p\ge1$ by Lemma~\ref{lem:fact} and the right term is $0$ by hypothesis, so $\check H^p(\cU,\cQ)=0$ for $p\ge1$.
494	
495	(c) \emph{Conclusion.} From $0\to G\to\cI\to\cQ\to0$ and $H^{>0}(U,\cI)=0$ we get $H^1(U,G)=\operatorname{coker}(\cI(U)\to\cQ(U))=0$ by (a), and $H^p(U,G)\cong H^{p-1}(U,\cQ)$ for $p\ge2$. Induction on $p$, applied to all sheaves satisfying the hypothesis at once, finishes the proof.
496	\end{proof}
497	
498	\subsection{Proof of the Main Theorem}
499	By Corollary~\ref{cor:unit}(c) and Proposition~\ref{prop:cartan}, $H^p(U,\pi^{-1}I^k)=0$ for $p>0$ and $U\in\fB$. Since $\pi^{-1}$ is exact, $\pi^{-1}F\to\pi^{-1}I^\bullet$ is a resolution by $\Gamma(U,-)$-acyclic sheaves. So for $U\in\fB$, $H^p(U,\pi^{-1}F)=H^p(I^\bullet(\Phi_U))$ (Corollary~\ref{cor:unit}(c)), which is $F(\Phi_U)$ for $p=0$ and $0$ for $p>0$ because $I^\bullet$ is an objectwise exact resolution of $F$.
500	
501	Since $\pi_*$ is restriction, taking an injective resolution $G\to\mathcal E^\bullet$ of a sheaf $G$ gives $(\mathrm R^p\pi_*G)(b)=H^p(\mathcal E^\bullet(b))=H^p(b,G)$, as cohomology of presheaves on $B_P$ is computed objectwise. Every $b\in B_P$ is f.p.\ (Lemma~\ref{lem:cov}), hence $\mathrm R^p\pi_*\pi^{-1}F=0$ for $p>0$. On $H^0$, the derived unit $F\to\pi_*\pi^{-1}F\to\mathrm R\pi_*\pi^{-1}F$ induces the underived unit, which is an isomorphism by Corollary~\ref{cor:unit}(b). So $F\to\mathrm R\pi_*\pi^{-1}F$ is a quasi-isomorphism. \qed
502	
503	\begin{thebibliography}{9}
504	\bibitem{SGA4}
505	M.~Artin, A.~Grothendieck, J.-L.~Verdier, \emph{Théorie des topos et cohomologie étale des schémas (SGA~4), Tome~1}, Lecture Notes in Mathematics 269, Springer, 1972.
506	
507	\bibitem{Fulton}
508	W.~Fulton, \emph{Introduction to Toric Varieties}, Annals of Mathematics Studies 131, Princeton University Press, 1993.
509	
510	\bibitem{Gordan}
511	P.~Gordan, Ueber die Auflösung linearer Gleichungen mit reellen Coefficienten, \emph{Math. Ann.} 6 (1873).
512	
513	\bibitem{Tohoku}
514	A.~Grothendieck, Sur quelques points d'algèbre homologique, \emph{Tôhoku Math. J.} (2) 9 (1957), 119--221.
515	
516	\bibitem{Hatcher}
517	A.~Hatcher, \emph{Algebraic Topology}, Cambridge University Press, 2002.
518	
519	\bibitem{MacLane}
520	S.~Mac~Lane, \emph{Categories for the Working Mathematician}, Graduate Texts in Mathematics 5, Springer, 1971.
521	
522	\bibitem{Schrijver}
523	A.~Schrijver, \emph{Theory of Linear and Integer Programming}, Wiley, 1986.
524	
525	\bibitem{Weibel}
526	C.~A.~Weibel, \emph{An Introduction to Homological Algebra}, Cambridge Studies in Advanced Mathematics 38, Cambridge University Press, 1994.
527	\end{thebibliography}
